fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(2);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut open: i32 = host::display::state_get(0);
    let mut count: i32 = host::display::state_get(1);
    let mx: i32 = w / 2 - 110;
    let my: i32 = h / 2 - 70;
    if down == 1 && prev == 0 {
        if open == 0 {
            if px >= 40 && px < 180 && py >= 60 && py < 104 {
                open = 1;
            }
        } else {
            if px >= mx + 20 && px < mx + 100 && py >= my + 80 && py < my + 116 {
                count = count + 1;
                host::display::state_set(1, count);
                open = 0;
            }
            if px >= mx + 120 && px < mx + 200 && py >= my + 80 && py < my + 116 {
                open = 0;
            }
        }
        host::display::state_set(0, open);
    }
    host::display::state_set(2, down);
    if open == 1 {
        host::display::clear(0x080808);
        host::display::fill_rect(mx - 3, my - 3, 226, 146, 0x606060);
        host::display::fill_rect(mx, my, 220, 140, 0x181820);
        host::display::draw_string(mx + 30, my + 30, "ARE YOU SURE?", 0xffffff, 2);
        host::display::fill_rect(mx + 20, my + 80, 80, 36, 0x882222);
        host::display::draw_string(mx + 40, my + 92, "YES", 0xffffff, 1);
        host::display::fill_rect(mx + 120, my + 80, 80, 36, 0x304050);
        host::display::draw_string(mx + 146, my + 92, "NO", 0xffffff, 1);
    } else {
        host::display::clear(0x101014);
        host::display::fill_rect(40, 60, 140, 44, 0x882222);
        host::display::draw_string(58, 76, "DELETE FILE", 0xffffff, 1);
        host::display::draw_string(40, 130, "DELETED", 0x808080, 1);
        host::display::draw_number(110, 130, count, 0xffffff, 2);
    }
    host::display::present();
}
